from pathlib import Path
import json
r=Path(__file__).resolve().parents[1]/'research/sites'
notes={
'01-skinspirit':('Split portrait hero with large serif text.','Dense treatment taxonomy with prominent booking.','Header booking and consultation alongside service categories.','Clinical experts and location-specific testimonials.','Pricing primarily inside treatment/booking paths.','Hero carousel; network captures media assets.','Cookie banner covers copy on first load. Promotional hero delays the evergreen proposition.','Treatment taxonomy','Organize services into clear clinical categories, with prices on each card.'),
'02-everbody':('Broad photo hero with direct clinical positioning.','Services, providers, philosophy and payment options are top-level.','Primary booking with treatment-discovery secondary.','Provider credentials and testimonial treatment labels.','Payment options visible in navigation.','Video testimonials and interactive concern selector.','Entry promotion obscures first impression; dismissed for clean recapture.','Concern-first discovery','An accessible concern selector maps plain-language goals to appropriate consultation paths.'),
'03-alchemy43':('Large typographic statement over a colorful editorial scene.','Services organized into injectables, skin, energy and wellness.','Book now appears in utility navigation and hero.','Expert-led positioning and detailed treatment-linked testimonials.','Offers emphasized over evergreen base costs.','Animated statement and moving proof strip.','Promotional modal and cookie panel compete with the brand; avoid that pattern.','Personalized treatment framing','Explain the conservative consult-plan-treat-maintain process using original language and a controlled 3D form.'),
'04-ject':('Quiet neutral split hero with natural portrait.','Two-tier navigation separates treatments from provider and location research.','Book and location discovery are paired.','Safety, efficacy and experience explain the operating approach.','Treatment cards give area-dependent pricing context.','Treatment carousel and image-led transitions.','Large newsletter block interrupts early flow; top navigation has many competing choices.','Treatment detail hierarchy','Use one-line benefit, clinical specs, risks, provider and price in a consistent detail template.'),
'05-heyday':('Warm yellow editorial facial offer, approachable typography.','Facials, locations, approach and membership have clear labels.','Book a facial repeated at intent points.','Training metrics and continuity of provider support care consistency.','Membership has explicit monthly fee and percentage benefits.','Skin renewal animation explains repeated care.','Promotions dominate opening content; some outcomes phrased too strongly.','Visible membership math','Show monthly cost, included care and honest savings versus individual visits; no invented popularity claim.')}
for slug,row in notes.items():
 p=r/slug
 if not (p/'capture.json').exists():continue
 d=json.loads((p/'capture.json').read_text())
 text='# '+slug+'\n\nSource: '+d['links'][0]['href'].split('/',3)[0]+'//'+d['links'][0]['href'].split('/')[2]+'\nCaptured: 2026-09-24 using Microsoft playwright-cli.\n\n'
 for heading,v in zip(['Hero','Navigation','CTA placement','Proof','Pricing','Motion','Weakness','Adopted element','Original adaptation'],row):text+='## '+heading+'\n'+v+'\n\n'
 text+='Inner page: '+d.get('inner',{}).get('url','pending')+'\n\nReference-only images: see images/sources.json. No assets approved for shipping.\n'
 (p/'notes.md').write_text(text)
